import { describe, expect, it } from "vitest";
import { markerVerdict } from "../../../utils/hunk-rules/generated";
import { lines } from "../../fixtures/head-scan";

describe("markerVerdict", () => {
  it.each([
    [
      "src/client/sdk.gen.ts",
      lines(
        "// This file is auto-generated by @hey-api/openapi-ts",
        "",
        'import type { Client } from "./client";',
      ),
      "generated",
    ],
    [
      "api/types.pb.go",
      lines(
        "//go:build linux",
        "// +build linux",
        "",
        "// Code generated by protoc-gen-go. DO NOT EDIT.",
        "",
        "package api",
      ),
      "generated",
    ],
    [
      "src/generated/schema.rs",
      lines("// @generated by fixture-schema", "pub struct Schema;"),
      "generated",
    ],
    [
      "src/licensed.ts",
      lines(
        "/*",
        " * Copyright 2026 Example",
        " * SPDX-License-Identifier: MIT",
        " */",
        "",
        "// @generated",
        "export const a = 1;",
      ),
      "generated",
    ],
    ["gen/models.py", lines("# @generated", "x = 1"), "generated"],
    ["gen/models.lua", lines("-- @generated", "local x = 1"), "generated"],
    ["api/crlf.go", lines("// Code generated by x. DO NOT EDIT.\r", "package api"), "generated"],
    ["src/late.ts", lines("export const a = 1;", "// @generated"), "not-generated"],
    ["src/by.ts", lines("// @generatedBy tool", "export const a = 1;"), "not-generated"],
    [
      "api/loose.go",
      lines("// Code generated by x. DO NOT EDIT. Really.", "package api"),
      "not-generated",
    ],
    ["src/open.ts", lines("/*", " * a long license"), "needs-content"],
    ["data/schema.json", lines("// @generated", "{}"), "not-generated"],
  ])("reads %s as %s", (path, body, verdict) =>
    expect(markerVerdict(path, body.split("\n"))).toBe(verdict),
  );
});
